SELECT emar.medication_complexity_quintile, COUNT(DISTINCT admissions.subject_id) AS patient_count, AVG(admissions.length_of_stay) AS avg_length_of_stay, MIN(admissions.length_of_stay) AS min_length_of_stay, MAX(admissions.length_of_stay) AS max_length_of_stay, SUM(CASE WHEN patients.dod IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(DISTINCT admissions.subject_id), 0) AS mortality_rate, SUM(CASE WHEN transfers.transfer_id IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(DISTINCT admissions.subject_id), 0) AS readmission_rate FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id LEFT JOIN transfers ON admissions.subject_id = transfers.subject_id AND admissions.hadm_id = transfers.hadm_id LEFT JOIN emar ON admissions.subject_id = emar.subject_id AND admissions.hadm_id = emar.hadm_id WHERE patients.gender = 'F' AND patients.age >= 76 AND patients.age <= 86 AND emar.cardiac_arrest = 'Y' AND (admissions.dischtime - admissions.admittime) <= 7 GROUP BY emar.medication_complexity_quintile ORDER BY emar.medication_complexity_quintile NULLS LAST;